const upsertInventory = `-- name: UpsertInventory :exec
INSERT INTO inventory (namespace, tool, name, unit_id, display_name, last_changed_ms, status, resource_count)
VALUES (?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (namespace, tool, name) DO UPDATE SET
    unit_id = excluded.unit_id,
    display_name = excluded.display_name,
    last_changed_ms = excluded.last_changed_ms,
    status = excluded.status,
    resource_count = excluded.resource_count
`

type UpsertInventoryParams struct {
	Namespace     string
	Tool          string
	Name          string
	UnitID        string
	DisplayName   string
	LastChangedMs int64
	Status        string
	ResourceCount sql.NullInt64
}

// The lock columns stay out of the upsert: other writes keep the lock a
// running update or a held workspace published, and only UpdateInventoryLock
// changes it.
func (q *Queries) UpsertInventory(ctx context.Context, arg UpsertInventoryParams) error {
	_, err := q.db.ExecContext(ctx, upsertInventory,
		arg.Namespace,
		arg.Tool,
		arg.Name,
		arg.UnitID,
		arg.DisplayName,
		arg.LastChangedMs,
		arg.Status,
		arg.ResourceCount,
	)
	return err
}
